<?php
const MOD = 998244353;

function mul($a, $b) {
    $n = count($a);
    $c = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($k = 0; $k < $n; $k++) {
