$inv = array_fill(0, $p, 0);
$inv[1] = 1;
for ($i = 2; $i < $p; $i++) {
    $inv[$i] = (int)(($p - (int)($p / $i)) * $inv[$p % $i] % $p);
}

// Precompute inverses of powers of a
$invPowA = array_fill(0, $pm1, 0);
for ($k = 0; $k < $pm1; $k++) {
    $invPowA[$k] = $inv[$powA[$k]];
}

// Build mapping from value to list of residues k mod (p-1) where a^k == value
$valToKs = array_fill(0, $p, []);
for ($k = 0; $k < $pm1; $k++) {
    $v = $powA[$k];
    $valToKs[$v][] = $k;
}

$ans = 0;
for ($r = 0; $r < $p; $r++) {
    $invPowAr = $invPowA[$r];
    $c = (int)(($b * $invPowAr) % $p);
    foreach ($valToKs[$c] as $k) {
        // Solve n ≡ r (mod p), n ≡ k (mod p-1)
        $t0 = ($r - $k) % $pm1;
        if ($t0 < 0) $t0 += $pm1;
        $n0 = $r + $p * $t0;
        $M = (int)($p * $pm1);
        if ($n0 == 0) {
            $first = $M;
        } else {
            $first = $n0;
        }
