<?php

const MAX_N = 18;

$lcmMemo = array_fill(0, 10, array_fill(0, 2521, -1));

function gcd($a, $b) {
    while ($b != 0) {
        $temp = $a % $b;
        $a = $b;
        $b = $temp;
    }
    return $a;
}

function lcm($a, $b) {
    if ($a == 0 || $b == 0) return 0;
    return ($a / gcd($a, $b)) * $b;
}

function getNextLcm($currentLcm, $digit) {
    global $lcmMemo;
    if ($lcmMemo[$digit][$currentLcm] != -1) {
        return $lcmMemo[$digit][$currentLcm];
    }
    if ($digit == 0) {
        $lcmMemo[$digit][$currentLcm] = $currentLcm;
        return $currentLcm;
    }
    if ($currentLcm == 1) {
        $lcmMemo[$digit][$currentLcm] = $digit;
        return $digit;
    }
    $res = lcm($currentLcm, $digit);
    $lcmMemo[$digit][$currentLcm] = $res;
    return $res;
}

$dpMemo = array_fill(0, MAX_N + 1, array_fill(0, 2521, array_fill(0, 2520, -1)));

function solveDP($pos, $lcmVal, $rem, $tight, $digits) {
    global $dpMemo;
    if ($pos == count($digits)) {
        return ($rem % $lcmVal == 0) ? 1 : 0;
    }
    if (!$tight && $dpMemo[$pos][$lcmVal][$rem] != -1) {
        return $dpMemo[$pos][$lcmVal][$rem];
    }
    $limit = $tight ? $digits[$pos] : 9;
    $ans = 0;
    for ($d = 0; $d <= $limit; $d++) {
        $nextLcm = getNextLcm($lcmVal, $d);
        $nextRem = ($rem * 10 + $d) % 2520;
        $nextTight = $tight && ($d == $limit);
        $ans += solveDP($pos + 1, $nextLcm, $nextRem, $nextTight, $digits);
    }
    if (!$tight) {
        $dpMemo[$pos][$lcmVal][$rem] = $ans;
    }
    return $ans;
}

function countBeautiful($x) {
    if ($x <= 0) return 0;
    $digits = str_split((string)$x);
    $digits = array_map('intval', $digits);
    return solveDP(0, 1, 0, true, $digits);
}

