<?php

const MOD = 998244353;

$n = intval(fgets(STDIN));
if ($n === 1) {
    echo "1\n";
    exit;
}

$adj = array_fill(1, $n, []);
for ($i = 0; $i < $n - 1; $i++) {
    $parts = explode(' ', trim(fgets(STDIN)));
    $u = (int)$parts[0];
    $v = (int)$parts[1];
    $adj[$u][] = $v;
    $adj[$v][] = $u;
}

$parent = array_fill(1, $n, 0);
$order = [1];
$parent[1] = -1;
for ($i = 0; $i < count($order); $i++) {
    $u = $order[$i];
    foreach ($adj[$u] as $v) {
        if ($v !== $parent[$u]) {
            $parent[$v] = $u;
            $order[] = $v;
        }
    }
}

$dp0 = array_fill(1, $n, 0); // u unmatched
$dp1 = array_fill(1, $n, 0); // u matched to parent
$dp2 = array_fill(1, $n, 0); // u matched to a child
$cnt0 = array_fill(1, $n, 0);
$cnt1 = array_fill(1, $n, 0);
$cnt2 = array_fill(1, $n, 0);

for ($i = $n - 1; $i >= 0; $i--) {
    $u = $order[$i];
    $children = [];
    foreach ($adj[$u] as $v) {
        if ($v !== $parent[$u]) {
            $children[] = $v;
        }
    }
    if (empty($children)) {
        $dp0[$u] = 0;
        $cnt0[$u] = 1;
        $dp1[$u] = 1;
        $cnt1[$u] = 1;
        $dp2[$u] = -1000000000;
        $cnt2[$u] = 0;
        continue;
    }

    // State 0: u unmatched
    $sum0 = 0;
    $ways0 = 1;
    foreach ($children as $v) {
        $best = max($dp0[$v], $dp2[$v]);
        $sum0 += $best;
        $c = 0;
        if ($dp0[$v] === $best) $c = ($c + $cnt0[$v]) % MOD;
        if ($dp2[$v] === $best) $c = ($c + $cnt2[$v]) % MOD;
        $ways0 = ($ways0 * $c) % MOD;
    }
    $dp0[$u] = $sum0;
    $cnt0[$u] = $ways0;

    // State 1: u matched to parent
    $sum1 = 0;
    $ways1 = 1;
    foreach ($children as $v) {
        $best = max($dp0[$v], $dp2[$v]);
        $sum1 += $best;
        $c = 0;
        if ($dp0[$v] === $best) $c = ($c + $cnt0[$v]) % MOD;
        if ($dp2[$v] === $best) $c = ($c + $cnt2[$v]) % MOD;
        $ways1 = ($ways1 * $c) % MOD;
    }
    $dp1[$u] = $sum1 + 1;
    $cnt1[$u] = $ways1;

    // State 2: u matched to a child
    // Consider matching u with child w
    // For w: value = dp1[w], ways = cnt1[w]
    // For others: best of dp0/dp2
    // Total match = sum_{v!=w} best + dp1[w] + 1
    // We need max over w of that total, and sum of ways for achieving max.

    // Precompute prefix/suffix products and sums for efficiency? n up to 3e5, sum of deg = 2n-2.
    // O(deg) per node is fine.
    $k = count($children);
    // Precompute best values and ways for each child
    $bestVal = [];
    $bestWays = [];
    $sumBest = 0;
    foreach ($children as $v) {
        $bv = max($dp0[$v], $dp2[$v]);
        $bestVal[] = $bv;
        $sumBest += $bv;
        $bw = 0;
        if ($dp0[$v] === $bv) $bw = ($bw + $cnt0[$v]) % MOD;
        if ($dp2[$v] === $bv) $bw = ($bw + $cnt2[$v]) % MOD;
        $bestWays[] = $bw;
    }

    $maxMatch2 = -1000000000;
    $totalWays2 = 0;

    for ($j = 0; $j < $k; $j++) {
        $v = $children[$j];
        $curMatch = $sumBest - $bestVal[$j] + $dp1[$v] + 1;
        if ($curMatch > $maxMatch2) {
            $maxMatch2 = $curMatch;
            $totalWays2 = 0;
        }
        if ($curMatch === $maxMatch2) {
            // ways = cnt1[v] * product_{i!=j} bestWays[i]
            // Compute product efficiently? For each node, deg can be large.
            // We can precompute prefix/suffix products of bestWays.
            // But since we are in a loop over children, doing O(k) per child makes O(k^2).
            // Need O(k).
        }
    }
    // To compute ways in O(k), use prefix/suffix products.
    $pref = [1];
    for ($j = 0; $j < $k; $j++) {
        $pref[] = ($pref[$j] * $bestWays[$j]) % MOD;
    }
    $suff = array_fill(0, $k + 1, 1);
    for ($j = $k - 1; $j >= 0; $j--) {
        $suff[$j] = ($suff[$j + 1] * $bestWays[$j]) % MOD;
    }

    $maxMatch2 = -1000000000;
    $totalWays2 = 0;
    for ($j = 0; $j < $k; $j++) {
        $v = $children[$j];
        $curMatch = $sumBest - $bestVal[$j] + $dp1[$v] + 1;
        if ($curMatch > $maxMatch2) {
            $maxMatch2 = $curMatch;
            $totalWays2 = 0;
        }
        if ($curMatch === $maxMatch2) {
            $waysOthers = ($pref[$j] * $suff[$j + 1]) % MOD;
            $totalWays2 = ($totalWays2 + $waysOthers * $cnt1[$v]) % MOD;
        }
    }
    $dp2[$u] = $maxMatch2;
    $cnt2[$u] = $totalWays2;
}

// Answer for root (1): max of dp0[1], dp2[1]
$ansMatch = max($dp0[1], $dp2[1]);
$ansWays = 0;
if ($dp0[1] === $ansMatch) $ansWays = ($ansWays + $cnt0[1]) % MOD;
if ($dp2[1] === $ansMatch) $ansWays = ($ansWays + $cnt2[1]) % MOD;

echo $ansWays . "\n";

