<?php

$stdin = fopen('php://stdin', 'r');
$n_line = fgets($stdin);
$n = intval(trim($n_line));
$s = trim(fgets($stdin));
$m = strlen($s);

if ($m > $n) {
    echo 0 . "\n";
    exit;
}

// Build prefix function (KMP) for s
$pi = array_fill(0, $m, 0);
for ($i = 1; $i < $m; $i++) {
    $j = $pi[$i - 1];
    while ($j > 0 && $s[$i] !== $s[$j]) {
        $j = $pi[$j - 1];
    }
    if ($s[$i] === $s[$j]) {
        $j++;
    }
    $pi[$i] = $j;
}

// Build automaton for states 0..m-1 (state m means match found -> absorbing/bad)
$next = array_fill(0, $m, [0, 0]);
for ($state = 0; $state < $m; $state++) {
    for ($c = 0; $c <= 1; $c++) {
        $ch = (string)$c;
        if ($state < $m && $ch === $s[$state]) {
            $next[$state][$c] = $state + 1;
        } else {
            if ($state === 0) {
                $next[$state][$c] = 0;
            } else {
                $next[$state][$c] = $next[$pi[$state - 1]][$c];
            }
        }
    }
}

// Compute M^len using binary exponentiation, matrix size m x m
function mat_mul($A, $B, $mod = null) {
    $n = count($A);
    $C = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) {
        for ($k = 0; $k < $n; $k++) {
            if ($A[$i][$k] === 0) continue;
            $aik = $A[$i][$k];
            for ($j = 0; $j < $n; $j++) {
                $C[$i][$j] += $aik * $B[$k][$j];
            }
        }
    }
    return $C;
}

function mat_pow($M, $exp) {
    $n = count($M);
    // Identity
    $R = array_fill(0, $n, array_fill(0, $n, 0));
    for ($i = 0; $i < $n; $i++) $R[$i][$i] = 1;
    $base = $M;
    while ($exp > 0) {
        if ($exp & 1) {
            $R = mat_mul($R, $base);
        }
        $base = mat_mul($base, $base);
        $exp >>= 1;
    }
    return $R;
}

// Build transition matrix T for states 0..m-1
$T = array_fill(0, $m, array_fill(0, $m, 0));
for ($i = 0; $i < $m; $i++) {
    for ($c = 0; $c <= 1; $c++) {
        $ns = $next[$i][$c];
        if ($ns < $m) {
            $T[$i][$ns]++;
        }
    }
}

// Compute T^n
$Tn = mat_pow($T, $n);

// Sum of row 0 of T^n = number of strings length n avoiding s
$avoid = 0;
for ($j = 0; $j < $m; $j++) {
    $avoid += $Tn[0][$j];
}

$total = 1 << $n; // 2^n, n <= 40 fits in 64-bit int
$ans = $total - $avoid;
echo $ans . "\n";
