<?php

function countNumbersWithOneZero($n) {
    if ($n <= 0) return 0;
    $count = 0;
    // Length of binary representation
    // Max n is 10^18 < 2^60. So max length is 60.
    for ($len = 2; $len <= 60; $len++) {
        $base = (1 << $len) - 1; // Number with all 1s of length $len
        if ($base > $n) break; // Smallest number of this length (with zero at MSB-1 pos) is base - 2^(len-2). If base > n, all numbers of this length > n.

        for ($k = 0; $k <= $len - 2; $k++) {
            $num = $base - (1 << $k);
            if ($num <= $n) {
                $count++;
            } else {
                // Since k increases, 2^k increases, num decreases.
                // If current num > n, smaller k (smaller 2^k, larger num) will also be > n.
                // So we can break inner loop.
                break;
            }
        }
    }
    return $count;
}

