<?php

function solve() {
    $stdin = fopen('php://stdin', 'r');
    $first_line = fgets($stdin);
    if ($first_line === false) return;
    $parts = explode(' ', trim($first_line));
    $n = (int)$parts[0];
    $m = (int)$parts[1];

    $grid = [];
    for ($i = 0; $i < $n; $i++) {
        $line = fgets($stdin);
        $row = array_map('intval', explode(' ', trim($line)));
        $grid[] = $row;
    }
    fclose($stdin);

    // Build bipartite graph
    // Partition A: cells where (i+j) % 2 == 0
    // Partition B: cells where (i+j) % 2 == 1
    // Map (i, j) to node IDs
    $node_id_a = [];
    $node_id_b = [];
    $count_a = 0;
    $count_b = 0;

    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $m; $j++) {
            if (($i + $j) % 2 == 0) {
                $node_id_a[$i][$j] = $count_a++;
            } else {
                $node_id_b[$i][$j] = $count_b++;
            }
        }
    }

    // Adjacency list for partition A
    $adj = array_fill(0, $count_a, []);

    $dr = [-1, 1, 0, 0];
    $dc = [0, 0, -1, 1];

    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $m; $j++) {
            if (($i + $j) % 2 != 0) continue; // Only process partition A nodes
            $u = $node_id_a[$i][$j];
            $val = $grid[$i][$j];
            for ($k = 0; $k < 4; $k++) {
                $ni = $i + $dr[$k];
                $nj = $j + $dc[$k];
                if ($ni >= 0 && $ni < $n && $nj >= 0 && $nj < $m) {
                    if ($grid[$ni][$nj] == $val) {
                        $v = $node_id_b[$ni][$nj];
                        $adj[$u][] = $v;
                    }
                }
            }
        }
    }

    // Hopcroft-Karp Algorithm
    $pairU = array_fill(0, $count_a, -1);
    $pairV = array_fill(0, $count_b, -1);
    $dist = array_fill(0, $count_a, 0);

    function bfs_hk($adj, &$pairU, &$pairV, &$dist, $count_a, $count_b) {
        $queue = new SplQueue();
        for ($u = 0; $u < $count_a; $u++) {
            if ($pairU[$u] == -1) {
                $dist[$u] = 0;
                $queue->enqueue($u);
            } else {
                $dist[$u] = -1; // INF
            }
        }
        $found_augmenting_path = false;
        while (!$queue->isEmpty()) {
            $u = $queue->dequeue();
            foreach ($adj[$u] as $v) {
                $pu = $pairV[$v];
                if ($pu != -1 && $dist[$pu] == -1) {
                    $dist[$pu] = $dist[$u] + 1;
                    $queue->enqueue($pu);
                }
                if ($pu == -1) {
                    $found_augmenting_path = true;
                }
            }
        }
        return $found_augmenting_path;
    }

    function dfs_hk($u, $adj, &$pairU, &$pairV, &$dist) {
        foreach ($adj[$u] as $v) {
            $pu = $pairV[$v];
            if ($pu == -1 || ($dist[$pu] == $dist[$u] + 1 && dfs_hk($pu, $adj, $pairU, $pairV, $dist))) {
                $pairU[$u] = $v;
                $pairV[$v] = $u;
                return true;
            }
        }
        $dist[$u] = -1;
        return false;
    }

    $matching = 0;
    while (bfs_hk($adj, $pairU, $pairV, $dist, $count_a, $count_b)) {
        for ($u = 0; $u < $count_a; $u++) {
            if ($pairU[$u] == -1) {
                if (dfs_hk($u, $adj, $pairU, $pairV, $dist)) {
                    $matching++;
                }
            }
        }
    }

    $total_pairs = ($n * $m) / 2;
    $min_moves = 2 * ($total_pairs - $matching);
    echo $min_moves . "\n";
}

solve();

