<?php

function solve() {
    $input = trim(file_get_contents("php://stdin"));
    if ($input === '') {
        return;
    }
    $tokens = preg_split('/\s+/', $input);
    $idx = 0;

    $n = (int)$tokens[$idx++];
    $m = (int)$tokens[$idx++];
    $k = (int)$tokens[$idx++];

    $a = array_fill(0, $n, array_fill(0, $m, 0));
    $b = array_fill(0, $n, array_fill(0, $m, 0));
    $c = array_fill(0, $n, array_fill(0, $m, 0));

    for ($i = 0; $i < $n; $i++) {
        $idx++; // skip planet name
        for ($j = 0; $j < $m; $j++) {
            $a[$i][$j] = (int)$tokens[$idx++];
            $b[$i][$j] = (int)$tokens[$idx++];
            $c[$i][$j] = (int)$tokens[$idx++];
        }
    }

    $ans = 0;

    for ($buy = 0; $buy < $n; $buy++) {
        for ($sell = 0; $sell < $n; $sell++) {
            if ($buy === $sell) continue;
            $items = [];
            for ($j = 0; $j < $m; $j++) {
                $profit = $b[$sell][$j] - $a[$buy][$j];
                if ($profit > 0) {
                    $items[] = [$profit, $c[$buy][$j]];
                }
            }
            if (empty($items)) continue;
            usort($items, function($x, $y) {
                return $y[0] - $x[0];
            });
            $rem = $k;
            $cur = 0;
            foreach ($items as $item) {
                $take = min($item[1], $rem);
                $cur += $take * $item[0];
                $rem -= $take;
                if ($rem === 0) break;
            }
            if ($cur > $ans) $ans = $cur;
        }
    }

    echo $ans . "\n";
}

solve();
