<?php

const MOD = 1000000007;

function modPow($a, $e) {
    $r = 1;
    $a %= MOD;
    while ($e > 0) {
        if ($e & 1) $r = ($r * $a) % MOD;
        $a = ($a * $a) % MOD;
        $e >>= 1;
    }
    return $r;
}

function modInv($x) {
    return modPow($x, MOD - 2);
}

function factorize($n) {
    $res = [];
    for ($p = 2; $p * $p <= $n; $p++) {
        if ($n % $p === 0) {
            $cnt = 0;
            while ($n % $p === 0) {
                $n /= $p;
                $cnt++;
            }
            $res[] = [$p, $cnt];
        }
    }
    if ($n > 1) {
        $res[] = [$n, 1];
    }
    return $res;
}

function solve() {
    $input = fgets(STDIN);
    if ($input === false) return;
    list($n_str, $k_str) = explode(' ', trim($input));
    $n = (int)$n_str;
    $k = (int)$k_str;

    $factors = factorize($n);

    $total_ans = 1;

    foreach ($factors as $factor) {
        list($p, $e) = $factor;
        $p_mod = $p % MOD;

        // Precompute p^j mod MOD for j=0..e
        $p_pows = [1];
        for ($i = 1; $i <= $e; $i++) {
            $p_pows[$i] = ($p_pows[$i-1] * $p_mod) % MOD;
        }

        // dp_prev[j] = expected value starting from p^j after processed steps so far
        // Initially (0 steps processed), value is p^j
        $dp_prev = $p_pows;

        for ($step = 1; $step <= $k; $step++) {
            // prefix_sum[j] = sum_{t=0}^j dp_prev[t]
            $prefix_sum = [];
            $sum = 0;
            for ($j = 0; $j <= $e; $j++) {
                $sum += $dp_prev[$j];
                if ($sum >= MOD) $sum -= MOD;
                $prefix_sum[$j] = $sum;
            }
            $dp_cur = [];
            for ($j = 0; $j <= $e; $j++) {
                $inv = modInv($j + 1);
                $dp_cur[$j] = (int)(($prefix_sum[$j] * $inv) % MOD);
            }
            $dp_prev = $dp_cur;
        }

        $total_ans = (int)(($total_ans * $dp_prev[$e]) % MOD);
    }

    echo $total_ans . "\n";
}

solve();

